const lockOverlappedBaseFeeInvoice = `-- name: LockOverlappedBaseFeeInvoice :one
SELECT invoice.id::text AS id, invoice.status, invoice.base_amount::text AS base_amount,
       invoice.base_fee_period_start::timestamptz AS base_fee_period_start,
       invoice.base_fee_period_end::timestamptz AS base_fee_period_end,
       (SELECT COUNT(*) FROM purser.billing_payments payment
        WHERE payment.invoice_id = invoice.id AND payment.status = 'pending')::bigint AS pending_payments
FROM purser.billing_invoices invoice
WHERE invoice.id = $1::text::uuid
  AND invoice.tenant_id = $2::text::uuid
FOR UPDATE OF invoice
`

type LockOverlappedBaseFeeInvoiceParams struct {
	InvoiceID string `db:"invoice_id" json:"invoice_id"`
	TenantID  string `db:"tenant_id" json:"tenant_id"`
}

type LockOverlappedBaseFeeInvoiceRow struct {
	ID                 string    `db:"id" json:"id"`
	Status             string    `db:"status" json:"status"`
	BaseAmount         string    `db:"base_amount" json:"base_amount"`
	BaseFeePeriodStart time.Time `db:"base_fee_period_start" json:"base_fee_period_start"`
	BaseFeePeriodEnd   time.Time `db:"base_fee_period_end" json:"base_fee_period_end"`
	PendingPayments    int64     `db:"pending_payments" json:"pending_payments"`
}

// Locks the base-fee invoice FindOverlappedBaseFeeInvoice found.
func (q *Queries) LockOverlappedBaseFeeInvoice(ctx context.Context, arg LockOverlappedBaseFeeInvoiceParams) (LockOverlappedBaseFeeInvoiceRow, error) {
	row := q.db.QueryRowContext(ctx, lockOverlappedBaseFeeInvoice, arg.InvoiceID, arg.TenantID)
	var i LockOverlappedBaseFeeInvoiceRow
	err := row.Scan(
		&i.ID,
		&i.Status,
		&i.BaseAmount,
		&i.BaseFeePeriodStart,
		&i.BaseFeePeriodEnd,
		&i.PendingPayments,
	)
	return i, err
}

const reduceUnpaidBaseFeeInvoice = `-- name: ReduceUnpaidBaseFeeInvoice :execrows
UPDATE purser.billing_invoices
SET amount = $1::text::numeric,
    presentment_amount_cents = $2::bigint,
    usage_details = usage_details || $3::jsonb,
    updated_at = NOW()
WHERE id = $4::text::uuid
  AND tenant_id = $5::text::uuid
  AND status IN ('pending', 'overdue')
`

type ReduceUnpaidBaseFeeInvoiceParams struct {
	Amount                 string          `db:"amount" json:"amount"`
	PresentmentAmountCents int64           `db:"presentment_amount_cents" json:"presentment_amount_cents"`
	Details                json.RawMessage `db:"details" json:"details"`
	InvoiceID              string          `db:"invoice_id" json:"invoice_id"`
	TenantID               string          `db:"tenant_id" json:"tenant_id"`
}

// Lowers a payable base-fee invoice to the share of its period that was used,
// presented at the rate it was issued at.
func (q *Queries) ReduceUnpaidBaseFeeInvoice(ctx context.Context, arg ReduceUnpaidBaseFeeInvoiceParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, reduceUnpaidBaseFeeInvoice,
		arg.Amount,
		arg.PresentmentAmountCents,
		arg.Details,
		arg.InvoiceID,
		arg.TenantID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const rewindMollieBalanceCursorForPendingSettlement = `-- name: RewindMollieBalanceCursorForPendingSettlement :execrows
UPDATE purser.mollie_balance_cursors
SET last_transaction_id = NULL,
    last_transaction_created_at = $1::timestamptz,
    updated_at = NOW()
WHERE last_transaction_created_at > $1::timestamptz
  AND EXISTS (
      SELECT 1 FROM purser.provider_settlements settlement
      WHERE settlement.tenant_id = $2::text::uuid
        AND settlement.provider = 'mollie'
        AND settlement.provider_payment_id = $3
        AND settlement.status = 'pending'
  )
`

type RewindMollieBalanceCursorForPendingSettlementParams struct {
	PaymentCreatedAt  time.Time `db:"payment_created_at" json:"payment_created_at"`
	TenantID          string    `db:"tenant_id" json:"tenant_id"`
	ProviderPaymentID string    `db:"provider_payment_id" json:"provider_payment_id"`
}

// Moves every Mollie balance cursor back to a payment's creation time while
// that payment's settlement is still pending, so the next read reaches the
// payment's balance transaction even though its local row was written after
// the cursor passed it.
func (q *Queries) RewindMollieBalanceCursorForPendingSettlement(ctx context.Context, arg RewindMollieBalanceCursorForPendingSettlementParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, rewindMollieBalanceCursorForPendingSettlement, arg.PaymentCreatedAt, arg.TenantID, arg.ProviderPaymentID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

