const upsertMollieBalanceCursor = `-- name: UpsertMollieBalanceCursor :exec
INSERT INTO purser.mollie_balance_cursors (balance_id, last_transaction_id, last_transaction_created_at, updated_at)
VALUES ($1, $2, $3::timestamptz, NOW())
ON CONFLICT (balance_id) DO UPDATE
SET last_transaction_id = EXCLUDED.last_transaction_id,
    last_transaction_created_at = EXCLUDED.last_transaction_created_at,
    updated_at = NOW()
WHERE purser.mollie_balance_cursors.last_transaction_id IS NOT DISTINCT FROM NULLIF($4::text, '')
  AND purser.mollie_balance_cursors.last_transaction_created_at IS NOT DISTINCT FROM $5::timestamptz
`

type UpsertMollieBalanceCursorParams struct {
	BalanceID                string         `db:"balance_id" json:"balance_id"`
	LastTransactionID        sql.NullString `db:"last_transaction_id" json:"last_transaction_id"`
	LastTransactionCreatedAt time.Time      `db:"last_transaction_created_at" json:"last_transaction_created_at"`
	ExpectedID               string         `db:"expected_id" json:"expected_id"`
	ExpectedCreatedAt        sql.NullTime   `db:"expected_created_at" json:"expected_created_at"`
}

func (q *Queries) UpsertMollieBalanceCursor(ctx context.Context, arg UpsertMollieBalanceCursorParams) error {
	_, err := q.db.ExecContext(ctx, upsertMollieBalanceCursor,
		arg.BalanceID,
		arg.LastTransactionID,
		arg.LastTransactionCreatedAt,
		arg.ExpectedID,
		arg.ExpectedCreatedAt,
	)
	return err
}
